const app = document.getElementById('app');
const overlayRoot = document.getElementById('overlay-root');
const categoryNames = {all:'Todos mezclados',shonen:'Shonen popular',classic:'Clásicos',isekai:'Isekai y fantasía'};
const state = {screen:'lobby', count:4, names:['','','',''], category:'all', players:[], revealIndex:0, revealOpen:false, turnIndex:0, recallIndex:null, recallOpen:false, toastTimer:null};
const esc = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const activePlayers = () => state.players.filter(player => !player.guessed);
const playerByIndex = index => state.players[index];
const initials = name => name.trim().split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase();
function showToast(message){
  const node=document.createElement('div');node.className='toast';node.setAttribute('role','status');node.textContent=message;document.body.appendChild(node);
  clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>node.remove(),2400);
}
function render(){
  overlayRoot.innerHTML='';
  if(state.screen==='lobby') renderLobby();
  else if(state.screen==='setup') renderSetup();
  else if(state.screen==='reveal') renderReveal();
  else if(state.screen==='round') renderRound();
  else renderSummary();
}
function renderLobby(){
  const inputs=Array.from({length:state.count},(_,i)=>`<label class="name-field"><span class="number">${String(i+1).padStart(2,'0')}</span><span class="sr-only">Nombre del jugador ${i+1}</span><input maxlength="22" autocomplete="off" data-name="${i}" placeholder="Nombre del jugador ${i+1}" value="${esc(state.names[i]||'')}"></label>`).join('');
  app.innerHTML=`<section class="screen"><div class="hero"><p class="eyebrow">Pasa el teléfono · juega en grupo</p><h1>¿Quién <span>soy?</span></h1><p class="lead">Todos conocen a los demás… menos a sí mismos. Haz preguntas, descubre tu personaje y no mires la pantalla equivocada. 👀</p></div><div class="panel"><div class="section-head"><span class="section-title">Jugadores</span><div class="counter"><button class="stepper" type="button" data-action="minus" aria-label="Quitar jugador">−</button><span class="count" aria-live="polite">${state.count}</span><button class="stepper" type="button" data-action="plus" aria-label="Añadir jugador">+</button></div></div><div class="player-grid">${inputs}</div><label class="field-label" for="category">Universo anime</label><div class="select-wrap"><select id="category">${Object.entries(categoryNames).map(([key,label])=>`<option value="${key}" ${state.category===key?'selected':''}>${label}</option>`).join('')}</select></div><p class="helper">Elige un mínimo de 2 y un máximo de 12 jugadores.</p><button class="button button-primary lobby-action" type="button" data-action="start">Comenzar partida <span aria-hidden="true">↗</span></button></div><p class="footnote">🎴 Personajes al azar · sin repetidos · todo se queda en este teléfono</p></section>`;
}
function syncLobby(){
  app.querySelectorAll('[data-name]').forEach(input=>{state.names[Number(input.dataset.name)]=input.value;input.classList.remove('invalid');});
  const selector=document.getElementById('category');if(selector)state.category=selector.value;
}
function startGame(){
  syncLobby();
  const names=state.names.slice(0,state.count).map(value=>value.trim());
  const inputs=[...app.querySelectorAll('[data-name]')];let invalid=false;
  names.forEach((name,index)=>{if(!name||/^jugador\s*\d+$/i.test(name)){inputs[index]?.classList.add('invalid');invalid=true;}});
  const normalized=names.map(name=>name.toLocaleLowerCase('es'));
  if(new Set(normalized).size!==normalized.length){
    const duplicate=normalized.findIndex((name,index)=>normalized.indexOf(name)!==index);inputs[duplicate]?.classList.add('invalid');
    showToast('Usen nombres distintos para no confundir los turnos.');return;
  }
  if(invalid){showToast('Escribe un nombre real para cada jugador.');inputs.find(input=>input.classList.contains('invalid'))?.focus();return;}
  const pool=characters.filter(character=>state.category==='all'||character.category===state.category);
  if(pool.length<state.count){showToast('No hay suficientes personajes para esa categoría.');return;}
  for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}
  state.players=names.map((name,index)=>({id:index,name,character:pool[index],guessed:false}));
  state.revealIndex=0;state.revealOpen=false;state.turnIndex=0;state.recallIndex=null;state.screen='setup';render();
}
function renderSetup(){
  const player=playerByIndex(state.revealIndex);const isRecall=state.recallIndex!==null;
  app.innerHTML=`<section class="screen center-screen"><div class="card-icon" aria-hidden="true">${isRecall?'🔐':'📱'}</div><p class="eyebrow">${isRecall?'Consulta privada':'Reparto secreto'} · ${state.revealIndex+1} de ${state.players.length}</p><h2>Pásale el teléfono a <span class="player-highlight">${esc(player.name)}</span>.</h2><p class="lead">Asegúrate de que nadie más mire. Cuando estés a solas, toca para ver los personajes de los demás.</p><div class="panel"><div class="notice">🙈 Tu personaje siempre estará oculto. No enseñes la pantalla mientras la revisas.</div><button class="button button-primary" type="button" data-action="open-reveal">Soy ${esc(player.name)}, ver personajes</button></div></section>`;
}
function characterList(viewerIndex){
  return `<div class="list">${state.players.map((player,index)=>{
    const own=index===viewerIndex;const known=player.guessed;
    const content=own?`<div class="character-name">??? <span class="own-tag">· ¡Ese eres tú!</span></div><div class="character-anime">🔒 Personaje oculto</div>`:`<div class="character-name">${esc(player.character.name)}</div><div class="character-anime">${esc(player.character.anime)}</div>`;
    const marker=own?'?':initials(player.name);
    return `<div class="character-row ${own?'own':''}"><div class="avatar" aria-hidden="true">${own?'🔒':esc(marker)}</div><div class="character-info"><div class="character-name">${esc(player.name)}</div>${content}</div>${known&&!own?'<span class="winner-badge">Adivinó</span>':''}</div>`;
  }).join('')}</div>`;
}
function openReveal(){state.revealOpen=true;renderReveal();}
function renderReveal(){
  const isRecall=state.recallIndex!==null;const viewerIndex=isRecall?state.recallIndex:state.revealIndex;const viewer=playerByIndex(viewerIndex);
  app.innerHTML=`<section class="screen"><div class="revealed-header"><p class="eyebrow">Vista secreta · solo ${esc(viewer.name)}</p><h2>Los personajes de la mesa</h2><p>Observa a todos menos a ti. Tu identidad está bloqueada a propósito.</p></div>${characterList(viewerIndex)}<button class="button button-primary" type="button" data-action="close-reveal">${isRecall?'Listo, volver a la ronda':'Listo, ocultar y pasar al siguiente'} <span aria-hidden="true">→</span></button></section>`;
}
function nextSetup(){
  state.revealOpen=false;
  if(state.recallIndex!==null){state.recallIndex=null;state.screen='round';render();return;}
  state.revealIndex++;
  if(state.revealIndex>=state.players.length){state.turnIndex=0;state.screen='round';}else state.screen='setup';
  render();
}
function currentTurn(){
  if(!state.players.length)return null;
  if(!state.players[state.turnIndex]||state.players[state.turnIndex].guessed){const next=nextActiveIndex(state.turnIndex-1);state.turnIndex=next;}
  return state.players[state.turnIndex]||null;
}
function nextActiveIndex(from){
  const total=state.players.length;
  for(let step=1;step<=total;step++){const index=(from+step+total)%total;if(!state.players[index].guessed)return index;}
  return -1;
}
function advanceTurn(){const next=nextActiveIndex(state.turnIndex);if(next<0){finishGame();return;}state.turnIndex=next;render();}
function markGuessed(){
  const player=currentTurn();if(!player)return;player.guessed=true;
  if(activePlayers().length===0){finishGame();return;}
  state.turnIndex=nextActiveIndex(state.turnIndex);render();showToast(`${player.name} lo adivinó. ¡Bien jugado!`);
}
function renderRound(){
  if(activePlayers().length===0){finishGame();return;}
  const player=currentTurn();const completed=state.players.length-activePlayers().length;
  app.innerHTML=`<section class="screen"><div class="round-top"><p class="eyebrow" style="margin:0">Ronda de preguntas</p><span class="pill">${completed}/${state.players.length} adivinados</span></div><div class="turn-card"><div class="turn-label">Turno de preguntar</div><div class="turn-name">${esc(player.name)}</div><div class="turn-hint">Haz una pregunta que se responda con sí o no.</div></div><button class="button button-primary" type="button" data-action="guess">¡${esc(player.name)} adivinó su personaje! 🎉</button><button class="button button-secondary" style="margin-top:10px" type="button" data-action="next-turn">Pasar al siguiente turno <span aria-hidden="true">→</span></button><div class="status-title"><span>Estado de la partida</span><span class="subtle">${activePlayers().length} por descubrir</span></div><div class="status-list">${state.players.map(person=>`<div class="status-row ${person.guessed?'done':''}"><span class="status-name">${esc(person.name)}</span><span class="status-state">${person.guessed?'✓ Adivinó':'Jugando'}</span></div>`).join('')}</div><div class="round-actions"><div class="secondary-actions"><button class="button button-quiet button-small" type="button" data-action="recall">👀 Olvidé los personajes</button><button class="button button-quiet button-small" type="button" data-action="finish">Terminar ronda</button></div></div><p class="footnote">Las preguntas se hacen en voz alta. Pasa el teléfono solo para consultas privadas.</p></section>`;
}
function finishGame(){state.screen='summary';state.recallIndex=null;render();}
function renderSummary(){
  const winners=state.players.filter(player=>player.guessed).length;
  app.innerHTML=`<section class="screen"><div class="summary-hero"><p class="eyebrow">Fin de la ronda</p><h2>${winners===state.players.length?'¡Misión cumplida!':'¡Se revelan las cartas!'}</h2><p>${winners===state.players.length?'Todo el grupo descubrió su identidad.':'Así queda el misterio de la mesa.'} ${winners} de ${state.players.length} adivinaron.</p></div><div class="panel"><div class="section-head"><span class="section-title">El reparto completo</span><span class="pill">${categoryNames[state.category]}</span></div><div class="list">${state.players.map(player=>`<div class="character-row"><div class="avatar">${esc(initials(player.name))}</div><div class="character-info"><div class="character-name">${esc(player.name)} <span class="winner-badge">${player.guessed?'· Adivinó':'· Revelado'}</span></div><div class="character-anime">${esc(player.character.name)} · ${esc(player.character.anime)}</div></div></div>`).join('')}</div></div><button class="button button-primary" style="margin-top:18px" type="button" data-action="replay">Jugar otra ronda <span aria-hidden="true">↻</span></button><button class="button button-quiet button-small" style="margin-top:10px" type="button" data-action="home">Volver al lobby</button><p class="footnote">Los nombres y la categoría se mantienen; los personajes se vuelven a sortear.</p></section>`;
}

