function renderSummary(){
  const winners=state.players.filter(player=>player.guessed).length;
  app.innerHTML=`<section class="screen"><div class="summary-hero"><p class="eyebrow">Fin de la ronda</p><h2>${winners===state.players.length?'¡Misión cumplida!':'¡Se revelan las cartas!'}</h2><p>${winners===state.players.length?'Todo el grupo descubrió su identidad.':'Así queda el misterio de la mesa.'} ${winners} de ${state.players.length} adivinaron.</p></div><div class="panel"><div class="section-head"><span class="section-title">El reparto completo</span><span class="pill">${categoryNames[state.category]}</span></div><div class="list">${state.players.map(player=>`<div class="character-row"><div class="avatar">${esc(initials(player.name))}</div><div class="character-info"><div class="character-name">${esc(player.name)} <span class="winner-badge">${player.guessed?'· Adivinó':'· Revelado'}</span></div><div class="character-anime">${esc(player.character.name)} · ${esc(player.character.anime)}</div></div></div>`).join('')}</div></div><button class="button button-primary" style="margin-top:18px" type="button" data-action="replay">Jugar otra ronda <span aria-hidden="true">↻</span></button><button class="button button-quiet button-small" style="margin-top:10px" type="button" data-action="home">Volver al lobby</button><p class="footnote">Los nombres y la categoría se mantienen; los personajes se vuelven a sortear.</p></section>`;
}

function showRecallDialog(){
  const turn=currentTurn();
  overlayRoot.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="recall-title"><h2 id="recall-title">Consulta rápida</h2><p>Elige quién está tomando el teléfono. ¿Seguro que eres esa persona? Solo verá los personajes de los demás.</p><label class="field-label" for="recall-player">Soy…</label><div class="select-wrap"><select id="recall-player">${state.players.map((player,index)=>`<option value="${index}" ${player.id===turn.id?'selected':''}>${esc(player.name)}</option>`).join('')}</select></div><button class="button button-primary" type="button" data-action="confirm-recall">Sí, soy esa persona</button><button class="button button-quiet button-small" type="button" data-action="cancel-modal">Cancelar</button></section></div>`;
  document.getElementById('recall-player')?.focus();
}
function beginRecall(){
  const selector=document.getElementById('recall-player');if(!selector)return;
  state.recallIndex=Number(selector.value);state.revealOpen=false;state.screen='setup';render();
}
function replay(){
  state.names=state.players.map(player=>player.name);state.count=state.players.length;state.screen='lobby';startGame();
}
function goHome(){
  state.names=state.players.map(player=>player.name);state.count=state.players.length;state.players=[];state.screen='lobby';render();
}
document.addEventListener('input',event=>{
  const input=event.target.closest('[data-name]');if(input){state.names[Number(input.dataset.name)]=input.value;input.classList.remove('invalid');}
});
document.addEventListener('change',event=>{if(event.target.id==='category')state.category=event.target.value;});
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button)return;
  switch(button.dataset.action){
    case 'minus': if(state.count>2){syncLobby();state.count--;state.names.length=state.count;renderLobby();}break;
    case 'plus': if(state.count<12){syncLobby();state.count++;state.names.length=state.count;renderLobby();}break;
    case 'start': startGame();break;
    case 'open-reveal':openReveal();break;
    case 'close-reveal':nextSetup();break;
    case 'next-turn':advanceTurn();break;
    case 'guess':markGuessed();break;
    case 'finish':finishGame();break;
    case 'recall':showRecallDialog();break;
    case 'confirm-recall':beginRecall();break;
    case 'cancel-modal':overlayRoot.innerHTML='';break;
    case 'replay':replay();break;
    case 'home':goHome();break;
  }
});
render();
</script>
</body>
</html>

